parameters.jsCode:
// Hands the email to Elliot (workflow 01, the same agent as WhatsApp and the
// website chat): answers from the knowledge base, listings with links,
// viewings booked with a confirmation email, hand-over to the team.
// Elliot's address: worked out from this n8n's own address, or pasted below.
const ELLIOT_CHAT_WEBHOOK_URL = 'PASTE_ELLIOT_CHAT_WEBHOOK_URL_HERE';

function setting(name, pasted) {
  try { if ($vars && $vars[name]) return String($vars[name]); } catch (e) {}
  try { if ($env && $env[name]) return String($env[name]); } catch (e) {}
  return String(pasted || '').startsWith('PASTE_') ? '' : String(pasted || '');
}

const f = $('Extract Email Fields').first().json;
const tenant = $('Find Agency').first().json;
const contact = $('Upsert Contact').first().json || {};
const conversationId = $input.first().json.id;

let url = setting('ELLIOT_CHAT_WEBHOOK_URL', ELLIOT_CHAT_WEBHOOK_URL);
if (!url) {
  let resume = '';
  try { resume = String($execution.resumeUrl || ''); } catch (e) {}
  const at = resume.indexOf('/webhook-waiting/');
  if (at > 0) url = resume.slice(0, at) + '/webhook/chat';
}
if (!url) {
  throw new Error("Can't work out Elliot's address: paste the chat webhook URL (workflow 01's Production URL) into ELLIOT_CHAT_WEBHOOK_URL in this node.");
}

return [{ json: {
  chat_url: url,
  request: {
    tenant_slug: tenant.tenant_slug,
    message: f.message,
    conversation_id: conversationId,
    channel: 'email',
    contact: { name: contact.name || f.from_name || null, email: f.from_email }
  }
} }];

// What Elliot (workflow 01) answered: { reply }, or { human: true } when a
// team member has taken the conversation over (then nothing is sent; they
// reply from the dashboard). If Elliot failed, the client still gets a short
// holding reply and the failure is logged.
const FALLBACK = "Thank you for your message. Someone from our team will get back to you shortly.";
const r = $input.first().json;
const status = Number(r.statusCode || 0);
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }
const req = $('Build Elliot Request').first().json.request;
const base = { conversation_id: req.conversation_id };
if (!(status >= 200 && status < 300) || !body || typeof body !== 'object') {
  return [{ json: { ...base, reply: FALLBACK, human: false, elliot_error: `Elliot answered with HTTP ${status || 'no response'}` } }];
}
if (body.human === true) return [{ json: { ...base, reply: '', human: true, elliot_error: null } }];
const reply = String(body.reply || '').trim();
return [{ json: { ...base, reply: reply || FALLBACK, human: false, elliot_error: reply ? null : 'Elliot returned an empty reply' } }];

// An email forwarded to <slug>@in.getelliot.eu, as Resend returns it
// (GET /emails/receiving/{id}): from, to, cc, subject, text, html, headers,
// message_id, received_for (who it was really delivered to). Same rules as
// the Gmail inbox (workflow 16): automatic emails are skipped and only the
// new part of a reply goes to Elliot. Gmail's "confirm forwarding" email is
// caught so the agency sees the code in Settings.
const r = $input.first().json;
let msg = r.body;
if (typeof msg === 'string') { try { msg = JSON.parse(msg); } catch (e) { msg = null; } }
const status = Number(r.statusCode || 0);
if (!(status >= 200 && status < 300) || !msg || typeof msg !== 'object' || !msg.id) {
  return [{ json: { skip: true, kind: 'fetch_failed', reason: `Resend answered with HTTP ${status || 'no response'}`, recipients: [] } }];
}

const headersIn = msg.headers || {};
function header(name) {
  const key = Object.keys(headersIn).find((k) => k.toLowerCase() === name.toLowerCase());
  const v = key ? headersIn[key] : '';
  return Array.isArray(v) ? String(v[0] || '') : String(v || '');
}
// "Anna Kowalska <anna@x.pl>" -> name + address
function person(v) {
  const s = String(v || '').trim();
  const m = s.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
  if (m) return { name: m[1].trim(), address: m[2].trim().toLowerCase() };
  return { name: '', address: s.replace(/^.*<|>.*$/g, '').trim().toLowerCase() };
}
const addrs = (v) => (Array.isArray(v) ? v : String(v || '').split(','))
  .map((x) => person(x).address).filter((a) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(a));

const fromHeader = person(header('from') || msg.from);
const fromEmail = fromHeader.address || person(msg.from).address;
const fromName = fromHeader.name;
const replyTo = addrs(msg.reply_to || header('reply-to'))[0] || '';
const recipients = [...new Set([...addrs(msg.to), ...addrs(msg.cc), ...addrs(msg.bcc), ...addrs(msg.received_for)])];
const subject = String(msg.subject || '').trim();

let text = String(msg.text || '');
if (!text.trim() && msg.html) {
  text = String(msg.html)
    .replace(/<(style|script)\b[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<(br|\/p|\/div|\/li|\/tr)\b[^>]*>/gi, '\n')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/[ \t]+/g, ' ');
}
text = text.replace(/\r\n/g, '\n');
const fullText = text;

// Gmail: "(#123456789) Gmail Forwarding Confirmation - Receive Mail from biuro@agency.pl"
if (fromEmail === 'forwarding-noreply@google.com') {
  const code = (subject.match(/#(\d{6,12})/) || fullText.match(/(?:code|kod)[^0-9]{0,40}(\d{6,12})/i) || [])[1] || null;
  const url = (fullText.match(/https:\/\/mail(?:-settings)?\.google\.com\/mail\/[^\s<>"]+/) || [])[0] || null;
  return [{ json: { skip: true, kind: 'gmail_forwarding', code, url, recipients, from_email: fromEmail, subject } }];
}

// Only the new part of a reply.
const cut = text.search(/\n[ \t]*(On\s[^\n]{0,200}(\n[^\n]{0,200})?\swrote:|W dniu\s[^\n]{0,200}(\n[^\n]{0,200})?\s(pisze|napisał\(a\)|napisała|napisał):|-{2,}\s*(Original Message|Wiadomość oryginalna|Forwarded message|Wiadomość przekazana dalej)|_{10,}\s*\n\s*(From|Od):)/i);
if (cut > 0) text = text.slice(0, cut);
const body = text.split('\n').filter((l) => !/^\s*>/.test(l)).join('\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, 4000);

// Who to answer: the Reply-To when the email has one from a real person
// (portal enquiries, e.g. Otodom or OLX, come from a no-reply address with the
// client in Reply-To), otherwise the sender.
const AUTO = /^(no-?reply|do-?not-?reply|mailer-daemon|postmaster|bounces?)([._+-]|$)/i;
const ours = (a) => /@(in|mail)\.getelliot\.eu$/i.test(a);
const useReplyTo = !!replyTo && replyTo !== fromEmail && !AUTO.test(replyTo.split('@')[0]) && !ours(replyTo);
const clientEmail = useReplyTo ? replyTo : fromEmail;
const clientName = useReplyTo ? '' : fromName;

const autoSubmitted = header('auto-submitted').toLowerCase();
const precedence = header('precedence').toLowerCase();
let skip = null;
if (!clientEmail) skip = 'no_sender';
else if (ours(clientEmail) || ours(fromEmail)) skip = 'sent_by_elliot';
else if (AUTO.test(clientEmail.split('@')[0])) skip = 'automatic_sender';
else if (autoSubmitted && autoSubmitted !== 'no') skip = 'auto_submitted';
else if (/bulk|list|junk/.test(precedence) || header('list-unsubscribe') || header('list-id')) skip = 'mailing_list';
else if (!body && !subject) skip = 'empty';

const rfcId = String(msg.message_id || header('message-id') || '').trim();
return [{ json: {
  skip: !!skip,
  kind: 'email',
  reason: skip,
  resend_id: msg.id,
  rfc_message_id: /^<.+>$/.test(rfcId) ? rfcId : (rfcId ? `<${rfcId}>` : ''),
  references: header('references'),
  from_email: clientEmail,
  from_name: clientName,
  recipients,
  subject,
  body,
  // What Elliot reads: the subject is often the whole question.
  message: subject && !/^(re|odp|fw|fwd|pd)\s*:/i.test(subject) ? `Subject: ${subject}\n\n${body || subject}` : (body || subject)
} }];

parameters.query:
-- An email reached in.getelliot.eu for an address no agency has.
insert into audit_log (tenant_id, actor_type, actor_id, event_type, details)
values (null, 'system', 'workflow_40', 'email_unmatched_mailbox', $1::jsonb);

-- 0039: each email answered once (by its Message-ID), and Settings shows
-- when the last forwarded email arrived.
select email_inbound_claim($1, $2, $3) as is_new;

parameters.jsCode:
// Elliot's answer as a reply in the client's thread: "Re:" subject,
// In-Reply-To / References set, plain text (Elliot's Markdown turned into clean
// text). Workflow 39 sends it from the agency's name, Reply-To the agency.
function toPlain(text) {
  let t = String(text || '').replace(/\r\n/g, '\n');
  t = t.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (m, label, url) => (label.trim() === url ? url : `${label.trim()}: ${url}`));
  t = t.replace(/\*\*(.+?)\*\*/g, '$1').replace(/__(.+?)__/g, '$1');
  t = t.replace(/^#{1,6}\s+/gm, '');
  t = t.replace(/^(\s*)\*\s+/gm, '$1- ');
  return t.replace(/\n{3,}/g, '\n\n').trim();
}
const f = $('Extract Email Fields').first().json;
const tenant = $('Find Agency').first().json;
const answer = $input.first().json;
const base = f.subject || 'Your enquiry';
const subject = /^(re|odp)\s*:/i.test(base) ? base : `Re: ${base}`;
const references = [f.references, f.rfc_message_id].filter(Boolean).join(' ').trim().slice(-900);
return [{ json: {
  tenant_id: tenant.tenant_id,
  conversation_id: answer.conversation_id,
  to: f.from_email,
  subject,
  text: toPlain(answer.reply) + '\n',
  in_reply_to: f.rfc_message_id || '',
  references,
} }];

// Workflow 39 answers { ok, error } (Resend's verdict).
const r = $input.first().json;
const sent = $('Build Reply Email').first().json;
const ok = r.ok === true;
return [{ json: { ok, error: ok ? null : ((r.error && r.error.message) || 'the email was not sent'), status: r.statusCode || null,
  tenant_id: sent.tenant_id, conversation_id: sent.conversation_id, to: sent.to, resend_id: r.id || null } }];
